- `POSTHOG_PROJECT_ID` (e.g. `521742`) ### Methods ```ts
import { postHogAdapter } from '@flags-sdk/posthog'; // Value - boolean flag. Pass the adapter uninvoked or invoked, both work.
export const myFlag = flag<boolean>({ key: 'my-flag', adapter: postHogAdapter, identify,
}); // Value - multivariate flag resolves to the variant string
export const myVariant = flag<string>({ key: 'my-flag', adapter: postHogAdapter, identify,
}); // Payload
export const myPayload = flag({ key: 'my-flag', adapter: postHogAdapter.payload, defaultValue: {}, identify,
