``` ## Marketing Pages Combine precompute with visitor ID generation for A/B tests on static pages: ### Middleware with visitor ID ```ts
// middleware.ts
import { rewrite } from '@vercel/edge';
import { parse } from 'cookie';
import { normalizeUrl } from '@sveltejs/kit';
import { computeInternalRoute, createVisitorId } from './src/lib/precomputed-flags'; export const config = { matcher: ['/examples/marketing-pages'] }; export default async function middleware(request: Request) { const { url, denormalize } = normalizeUrl(request.url); let visitorId = parse(request.headers.get('cookie') ?? '').visitorId || ''; if (!visitorId) { visitorId = createVisitorId; request.headers.set('x-visitorId', visitorId); } return rewrite( denormalize(await computeInternalRoute(url.pathname, request)), );
}
``` ### Flags with identify ```ts
// src/lib/flags.ts
import { flag } from 'flags/sveltekit'; interface Entities { visitorId?: string;
} function identify({ cookies, headers }) { const visitorId = cookies.get('visitorId')?.value ?? headers.get('x-visitorId'); if (!visitorId) throw new Error('Visitor ID not found'); return { visitorId };
} export const firstMarketingABTest = flag<boolean, Entities>({ key: 'firstMarketingABTest', identify, decide({ entities }) { if (!entities?.visitorId) return false; return /^[a-n0-5]/i.test(entities.visitorId); },
});
``` The `x-visitorId` header ensures the visitor ID is available even on the first request before the cookie is set.

