// embed.js
import { pipeline } from '@huggingface/transformers'; async function generateEmbedding(text) { const extractor = await pipeline( 'feature-extraction', 'onnx-community/all-MiniLM-L6-v2-ONNX' ); const output = await extractor(text, { pooling: 'mean', normalize: true }); console.log('Text:', text); console.log('Embedding dimensions:', output.data.length); console.log('First 5 values:', Array.from(output.data).slice(0, 5)); await extractor.dispose;
} generateEmbedding('Hello, world!');
``` ### Batch Processing ```javascript
// batch-embed.js
import { pipeline } from '@huggingface/transformers';
import fs from 'fs/promises'; async function embedDocuments(documents) { const extractor = await pipeline( 'feature-extraction', 'onnx-community/all-MiniLM-L6-v2-ONNX' ); console.log(`Processing ${documents.length} documents...`); const embeddings = []; for (let i = 0; i < documents.length; i++) { const output = await extractor(documents[i], { pooling: 'mean', normalize: true }); embeddings.push({ text: documents[i], embedding: Array.from(output.data) }); console.log(`Processed ${i + 1}/${documents.length}`); } await fs.writeFile( 'embeddings.json', JSON.stringify(embeddings, null, 2) ); console.log('Saved to embeddings.json'); await extractor.dispose;
