// cli-embed.js
import { pipeline } from '@huggingface/transformers'; async function main { const text = process.argv[2] || 'Hello, world!'; console.log('Loading model...'); const fileProgress = {}; const extractor = await pipeline( 'feature-extraction', 'onnx-community/all-MiniLM-L6-v2-ONNX', { progress_callback: (info) => { if (info.status === 'progress_total') { process.stdout.write(`\r\x1b[KTotal: ${info.progress.toFixed(1)}%`); return; } if (info.status === 'progress') { fileProgress[info.file] = info.progress; // Show all files progress const progressLines = Object.entries(fileProgress) .map(([file, progress]) => ` ${file}: ${progress.toFixed(1)}%`) .join('\n'); process.stdout.write(`\r\x1b[K${progressLines}`); } if (info.status === 'done') { console.log(`\n✓ ${info.file} complete`); } if (info.status === 'ready') { console.log('\nModel ready!'); } } } ); console.log('Generating embedding...'); const output = await extractor(text, { pooling: 'mean', normalize: true }); console.log(`\nText: "${text}"`); console.log(`Dimensions: ${output.data.length}`); console.log(`First 5 values: ${Array.from(output.data).slice(0, 5).join(', ')}`); await extractor.dispose;
} main;
