bled={loading || !text}> {loading ? 'Processing...' : 'Generate Embedding'} </button> {embedding && ( <div> <h3>Result:</h3> <p>Dimensions: {embedding.length}</p> <p>First 5 values: {embedding.slice(0, 5).join(', ')}</p> </div> )} </div> );
