// server-with-shutdown.js
import express from 'express';
import { pipeline } from '@huggingface/transformers'; const app = express;
app.use(express.json); let extractor;
let server; async function initialize { console.log('Loading model...'); extractor = await pipeline( 'feature-extraction', 'onnx-community/all-MiniLM-L6-v2-ONNX' ); console.log('Model ready!');
} app.post('/embed', async (req, res) => { try { const { text } = req.body; if (!text) { return res.status(400).json({ error: 'Text is required' }); } const output = await extractor(text, { pooling: 'mean', normalize: true }); res.json({ embedding: Array.from(output.data), dimensions: output.data.length }); } catch (error) { res.status(500).json({ error: error.message }); }
}); async function shutdown(signal) { console.log(`\n${signal} received. Shutting down...`); if (server) { server.close( => { console.log('HTTP server closed'); }); } if (extractor) { console.log('Disposing model...'); await extractor.dispose; console.log('Model disposed'); } process.exit(0);
} process.on('SIGTERM', => shutdown('SIGTERM'));
process.on('SIGINT', => shutdown('SIGINT')); initialize.then( => { server = app.listen(3000, => { console.log('Server running on http://localhost:3000'); });
});
``` --- These examples demonstrate the same functionality across different runtimes and frameworks, making it easy to adapt to your specific use case. All examples include proper cleanup with `.dispose` to free memory. --- file: references/MODEL_ARCHITECTURES.md ---
